std::string trim_type(std::string s){s.erase(std::remove_if(s.begin(),s.end(),[](unsigned char c){return c==' '||c=='\t'||c=='\n'||c=='\r';}),s.end());return s;}
char kind_from_type(const std::string &raw){std::string t=trim_type(raw);if(t=="string"||t=="System.String")return 's';if(t=="bool"||t=="System.Boolean")return 'b';if(t=="byte"||t=="System.Byte")return 'C';if(t=="sbyte"||t=="System.SByte")return 'c';if(t=="short"||t=="System.Int16")return 'h';if(t=="ushort"||t=="System.UInt16")return 'H';if(t=="int"||t=="System.Int32")return 'i';if(t=="uint"||t=="System.UInt32")return 'I';if(t=="long"||t=="System.Int64")return 'l';if(t=="ulong"||t=="System.UInt64")return 'L';if(t=="float"||t=="System.Single")return 'f';if(t=="double"||t=="System.Double")return 'd';return 'o';}
