void set_error(std::string *error,const std::string &message){if(error&&error->empty())*error=message;}
std::string class_name(const il2cpp::Api &a,void *k){const char *n=a.class_get_name?a.class_get_name(k):nullptr;return n?n:"";}
std::string class_full_name(const il2cpp::Api &a,void *k){std::string n=class_name(a,k);const char *ns=a.class_get_namespace?a.class_get_namespace(k):nullptr;return ns&&*ns?std::string(ns)+"."+n:n;}
bool is_pair_type(const std::string &type){return type.find("KeyValuePair<")!=std::string::npos||type.find("ValueTuple<")!=std::string::npos;}
