class GcPin {
public:
    GcPin(il2cpp::Runtime &runtime,void *object):runtime_(runtime){if(object)handle_=runtime_.retain(object,true);}
    ~GcPin(){if(handle_)runtime_.release(handle_);}
    GcPin(const GcPin&)=delete;GcPin& operator=(const GcPin&)=delete;
    bool ok() const{return handle_!=0;}
private:
    il2cpp::Runtime &runtime_;uint32_t handle_=0;
};
